	private SailDataset openStore(Shape shape) throws IOException {
		LmdbStore store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true).setDirectAdjacencyEnabled(true));
		repository = new SailRepository(store);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			shape.populate(connection.getValueFactory(), connection);
			connection.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store))
				.as("the admitted collector has a completed native adjacency index before evaluation")
				.isTrue();
		return NativeQuerySourceAccess.openExplicitDataset(store);
	}

	private void configure(String name, String value) {
		previousProperties.putIfAbsent(name, System.getProperty(name));
		System.setProperty(name, value);
	}

	@AfterEach
	void tearDown() {
		try {
			if (repository != null) {
				repository.shutDown();
				repository = null;
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			previousProperties.forEach((name, value) -> {
				if (value == null) {
					System.clearProperty(name);
				} else {
					System.setProperty(name, value);
				}
			});
			previousProperties.clear();
		}
	}

	private static Group firstGroup(TupleExpr expression) {
		List<Group> groups = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Group group) {
				groups.add(group);
				super.meet(group);
			}
		});
		assertThat(groups).as("the structural query has a group operator").isNotEmpty();
		return groups.getFirst();
	}

	private static List<BindingSet> evaluate(QueryEvaluationStep step) {
		try (CloseableIteration<BindingSet> rows = step.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(rows);
		}
	}

	private enum Shape {
		PREDICATE_PLANES(PREDICATE_QUERY, LmdbNativeAttemptMetrics.PATH_PREDICATE_PLANE_GROUPS,
				LmdbNativePredicatePlaneGroups.class, 256),
		DATATYPE_HISTOGRAM(DATATYPE_QUERY, LmdbNativeAttemptMetrics.PATH_DATATYPE_HISTOGRAM,
				LmdbNativeDatatypeHistogram.class, 256),
		RUN_COUNT_HISTOGRAM(RUN_COUNT_QUERY, LmdbNativeAttemptMetrics.PATH_RUN_COUNT_HISTOGRAM,
				LmdbNativeRunCountHistogram.class, 256);

		final String query;
		final String tag;
		final Class<?> implementation;
		final int expectedGroups;

		Shape(String query, String tag, Class<?> implementation, int expectedGroups) {
			this.query = query;
			this.tag = tag;
			this.implementation = implementation;
			this.expectedGroups = expectedGroups;
		}

		void populate(ValueFactory valueFactory, SailRepositoryConnection connection) {
			switch (this) {
			case PREDICATE_PLANES -> populatePredicates(valueFactory, connection);
			case DATATYPE_HISTOGRAM -> populateDatatypes(valueFactory, connection);
			case RUN_COUNT_HISTOGRAM -> populateDegrees(valueFactory, connection);
			}
		}

		long runs() {
			return switch (this) {
			case PREDICATE_PLANES -> LmdbNativePredicatePlaneGroups.RUNS.get();
			case DATATYPE_HISTOGRAM -> LmdbNativeDatatypeHistogram.RUNS.get();
			case RUN_COUNT_HISTOGRAM -> LmdbNativeRunCountHistogram.RUNS.get();
			};
		}

		void assertPayloadPressure(List<BindingSet> expected) {
			if (this == PREDICATE_PLANES) {
				assertThat(expected)
						.allSatisfy(row -> assertThat(row.getValue("ns").stringValue()).hasSizeGreaterThan(192));
			} else if (this == DATATYPE_HISTOGRAM) {
				assertThat(expected)
						.allSatisfy(row -> assertThat(row.getValue("datatype").stringValue()).hasSizeGreaterThan(192));
			}
		}

		void warmSourceValues(SyntheticValueSource evaluation, NativeLmdbQuerySource source) {
			if (this == PREDICATE_PLANES) {
				for (int group = 0; group < 256; group++) {
					String namespace = EX + "namespace/" + String.format("%03d", group) + "/" + LONG_NAMESPACE + "/";
					warm(evaluation, source, SimpleValueFactory.getInstance().createIRI(namespace + "p1"),
							ValuePosition.PREDICATE);
					warm(evaluation, source, SimpleValueFactory.getInstance().createIRI(namespace + "p2"),
							ValuePosition.PREDICATE);
				}
			} else if (this == DATATYPE_HISTOGRAM) {
				for (int group = 0; group < 256; group++) {
					IRI datatype = SimpleValueFactory.getInstance()
							.createIRI(EX + "datatype/" + String.format("%03d", group) + "/" + LONG_DATATYPE);
					warm(evaluation, source, SimpleValueFactory.getInstance().createLiteral("first-" + group, datatype),
							ValuePosition.OBJECT);
					warm(evaluation, source,
							SimpleValueFactory.getInstance().createLiteral("second-" + group, datatype),
							ValuePosition.OBJECT);
					long literalId = source.idOf(
							SimpleValueFactory.getInstance().createLiteral("first-" + group, datatype),
							ValuePosition.OBJECT);
					long datatypeId = source.literalDatatypeId(literalId);
					assertThat(datatypeId).as("the custom literal header exposes its stored datatype id").isPositive();
					assertThat(evaluation.lazyValue(datatypeId)).isEqualTo(datatype);
				}
			}
		}

		private static void warm(SyntheticValueSource evaluation, NativeLmdbQuerySource source,
				Value value, int positionMask) {
			long id = source.idOf(value, positionMask);
			assertThat(id).as("the fixture's actual term is present before the source-only ledger baseline")
					.isPositive();
			assertThat(evaluation.lazyValue(id, positionMask)).isEqualTo(value);
		}

		private static void populatePredicates(ValueFactory vf, SailRepositoryConnection connection) {
			for (int group = 0; group < 256; group++) {
				String namespace = EX + "namespace/" + String.format("%03d", group) + "/" + LONG_NAMESPACE + "/";
				IRI p1 = vf.createIRI(namespace + "p1");
				IRI p2 = vf.createIRI(namespace + "p2");
				connection.add(vf.createIRI(EX + "subject/" + group + "/1"), p1,
						vf.createIRI(EX + "object/" + group + "/1"));
				connection.add(vf.createIRI(EX + "subject/" + group + "/2"), p2,
						vf.createIRI(EX + "object/" + group + "/2"));
				connection.add(vf.createIRI(EX + "subject/" + group + "/3"), p2,
						vf.createIRI(EX + "object/" + group + "/3"));
			}
		}

		private static void populateDatatypes(ValueFactory vf, SailRepositoryConnection connection) {
			IRI predicate = vf.createIRI(EX + "literal");
			for (int group = 0; group < 256; group++) {
				IRI datatype = vf.createIRI(EX + "datatype/" + String.format("%03d", group) + "/" + LONG_DATATYPE);
				connection.add(vf.createIRI(EX + "subject/" + group + "/1"), predicate,
						vf.createLiteral("first-" + group, datatype));
				connection.add(vf.createIRI(EX + "subject/" + group + "/2"), predicate,
						vf.createLiteral("second-" + group, datatype));
			}
		}

		private static void populateDegrees(ValueFactory vf, SailRepositoryConnection connection) {
			IRI predicate = vf.createIRI(EX + "edge");
			for (int degree = 1; degree <= 256; degree++) {
				IRI subject = vf.createIRI(EX + "subject/degree/" + degree);
				for (int edge = 0; edge < degree; edge++) {
					connection.add(subject, predicate,
							vf.createIRI(EX + "object/degree/" + degree + "/" + edge));
				}
			}
		}
	}
